ffi_fn ! { #[doc = " Set the preferred HTTP version of the request."] #[doc = ""] #[doc = " The version value should be one of the `HYPER_HTTP_VERSION_` constants."] #[doc = ""] #[doc = " Note that this won't change the major HTTP version of the connection,"] #[doc = " since that is determined at the handshake step."] fn hyper_request_set_version (req : * mut hyper_request , version : c_int) -> hyper_code { use http :: Version ; let req = non_null ! (& mut * req ?= hyper_code :: HYPERE_INVALID_ARG) ; * req . 0 . version_mut () = match version { super :: HYPER_HTTP_VERSION_NONE => Version :: HTTP_11 , super :: HYPER_HTTP_VERSION_1_0 => Version :: HTTP_10 , super :: HYPER_HTTP_VERSION_1_1 => Version :: HTTP_11 , super :: HYPER_HTTP_VERSION_2 => Version :: HTTP_2 , _ => { return hyper_code :: HYPERE_INVALID_ARG ;}
} ; hyper_code :: HYPERE_OK}
}